    static void testByteCollections() {
        TByteHashSet set = new TByteHashSet(new byte[] {1, 2, 2, 3});
        ContractSuite.check(set.size() == 3 && !set.add((byte)2), "Byte:set duplicates");
        set.removeAll(new byte[] {2, 4});
        set.addAll(new byte[] {4, 5});
        set.retainAll(new byte[] {1, 4});
        ContractSuite.check(set.containsAll(new byte[] {1, 4}) && set.size() == 2, "Byte:set bulk");
        TByteHashSet clone = (TByteHashSet)set.clone();
        clone.clear();
        ContractSuite.check(set.size() == 2, "Byte:set clone");
        java.util.Set<Byte> decorated = new TByteHashSetDecorator(set);
        decorated.remove((byte)1);
        ContractSuite.check(!set.contains((byte)1), "Byte:set decorator");
        TByteIterator iterator = set.iterator();
        iterator.next(); iterator.remove();
        ContractSuite.check(set.isEmpty(), "Byte:set iterator");

        TByteArrayList list = new TByteArrayList(new byte[] {1, 2, 3});
        list.insert(1, new byte[] {4, 5});
        ContractSuite.check(list.size() == 5 && list.get(2) == 5, "Byte:list insert");
        list.remove(1, 2); list.add((byte)4); list.reverse();
        ContractSuite.check(list.get(0) == 4 && list.get(3) == 1, "Byte:list reverse");
        list.sort();
        ContractSuite.check(list.binarySearch((byte)3) == 2, "Byte:list search");
        list.fill(1, 3, (byte)7);
        ContractSuite.check(list.get(1) == 7 && list.get(0) == 1, "Byte:list fill");
        list.transformValues(v -> (byte)(v + 1));
        ContractSuite.check(list.grep(v -> v > 5).size() == 2, "Byte:list grep");
        ContractSuite.check(list.inverseGrep(v -> v > 5).size() == 2, "Byte:list inverseGrep");
        TByteArrayList copy = (TByteArrayList)list.clone();
        copy.set(0, (byte)42);
        ContractSuite.check(list.get(0) == 2, "Byte:list clone");
        byte[] target = new byte[8]; list.toNativeArray(target, 0, list.size());
        ContractSuite.check(target[0] == 2 && target[4] == 0, "Byte:list array");
        list.resetQuick(); list.add((byte)9); list.trimToSize();
        ContractSuite.check(list.size() == 1 && list.get(0) == 9, "Byte:list reset");

        TObjectByteHashMap<String> objects = new TObjectByteHashMap<>();
        objects.put("zero", (byte)0); objects.put("one", (byte)1);
        ContractSuite.check(objects.containsKey("zero") && !objects.containsKey("missing"), "Byte:object sentinel");
        objects.adjustValue("one", (byte)2);
        ContractSuite.check(objects.get("one") == 3, "Byte:object adjustment");
        objects.transformValues(v -> (byte)(v + 2));
        objects.retainEntries((k, v) -> k.equals("one"));
        ContractSuite.check(objects.size() == 1 && objects.get("one") == 5, "Byte:object retain");
        new TObjectByteHashMapDecorator<String>(objects).clear();
        ContractSuite.check(objects.isEmpty(), "Byte:object decorator");

        TByteObjectHashMap<String> primitive = new TByteObjectHashMap<>();
        primitive.put((byte)0, null); primitive.put((byte)1, "one");
        ContractSuite.check(primitive.containsKey((byte)0) && primitive.get((byte)0) == null, "Byte:primitive null");
        TByteObjectHashMap<String> pc = (TByteObjectHashMap<String>)primitive.clone();
        pc.put((byte)1, "copy");
        ContractSuite.check(primitive.get((byte)1).equals("one"), "Byte:primitive clone");
        new TByteObjectHashMapDecorator<String>(primitive).remove((byte)1);
        ContractSuite.check(!primitive.containsKey((byte)1), "Byte:primitive decorator");
    }


