    static void testIntCollections() {
        TIntHashSet set = new TIntHashSet(new int[] {1, 2, 2, 3});
        ContractSuite.check(set.size() == 3 && !set.add((int)2), "Int:set duplicates");
        set.removeAll(new int[] {2, 4});
        set.addAll(new int[] {4, 5});
        set.retainAll(new int[] {1, 4});
        ContractSuite.check(set.containsAll(new int[] {1, 4}) && set.size() == 2, "Int:set bulk");
        TIntHashSet clone = (TIntHashSet)set.clone();
        clone.clear();
        ContractSuite.check(set.size() == 2, "Int:set clone");
        java.util.Set<Integer> decorated = new TIntHashSetDecorator(set);
        decorated.remove((int)1);
        ContractSuite.check(!set.contains((int)1), "Int:set decorator");
        TIntIterator iterator = set.iterator();
        iterator.next(); iterator.remove();
        ContractSuite.check(set.isEmpty(), "Int:set iterator");

        TIntArrayList list = new TIntArrayList(new int[] {1, 2, 3});
        list.insert(1, new int[] {4, 5});
        ContractSuite.check(list.size() == 5 && list.get(2) == 5, "Int:list insert");
        list.remove(1, 2); list.add((int)4); list.reverse();
        ContractSuite.check(list.get(0) == 4 && list.get(3) == 1, "Int:list reverse");
        list.sort();
        ContractSuite.check(list.binarySearch((int)3) == 2, "Int:list search");
        list.fill(1, 3, (int)7);
        ContractSuite.check(list.get(1) == 7 && list.get(0) == 1, "Int:list fill");
        list.transformValues(v -> (int)(v + 1));
        ContractSuite.check(list.grep(v -> v > 5).size() == 2, "Int:list grep");
        ContractSuite.check(list.inverseGrep(v -> v > 5).size() == 2, "Int:list inverseGrep");
        TIntArrayList copy = (TIntArrayList)list.clone();
        copy.set(0, (int)42);
        ContractSuite.check(list.get(0) == 2, "Int:list clone");
        int[] target = new int[8]; list.toNativeArray(target, 0, list.size());
        ContractSuite.check(target[0] == 2 && target[4] == 0, "Int:list array");
        list.resetQuick(); list.add((int)9); list.trimToSize();
        ContractSuite.check(list.size() == 1 && list.get(0) == 9, "Int:list reset");

        TObjectIntHashMap<String> objects = new TObjectIntHashMap<>();
        objects.put("zero", (int)0); objects.put("one", (int)1);
        ContractSuite.check(objects.containsKey("zero") && !objects.containsKey("missing"), "Int:object sentinel");
        objects.adjustValue("one", (int)2);
        ContractSuite.check(objects.get("one") == 3, "Int:object adjustment");
        objects.transformValues(v -> (int)(v + 2));
        objects.retainEntries((k, v) -> k.equals("one"));
        ContractSuite.check(objects.size() == 1 && objects.get("one") == 5, "Int:object retain");
        new TObjectIntHashMapDecorator<String>(objects).clear();
        ContractSuite.check(objects.isEmpty(), "Int:object decorator");

        TIntObjectHashMap<String> primitive = new TIntObjectHashMap<>();
        primitive.put((int)0, null); primitive.put((int)1, "one");
        ContractSuite.check(primitive.containsKey((int)0) && primitive.get((int)0) == null, "Int:primitive null");
        TIntObjectHashMap<String> pc = (TIntObjectHashMap<String>)primitive.clone();
        pc.put((int)1, "copy");
        ContractSuite.check(primitive.get((int)1).equals("one"), "Int:primitive clone");
        new TIntObjectHashMapDecorator<String>(primitive).remove((int)1);
        ContractSuite.check(!primitive.containsKey((int)1), "Int:primitive decorator");
    }


