    static void testFloatByte() {
        TFloatByteHashMap map = new TFloatByteHashMap(1);
        byte[] values = new byte[64];
        boolean[] present = new boolean[64];
        int size = 0;
        for (int step = 0; step < 1200; step++) {
            int slot = ContractSuite.next() & 63;
            float key = (float)(slot - 32);
            byte value = (byte)((ContractSuite.next() & 127) - 64);
            if ((step & 3) != 0) {
                ContractSuite.check(map.put(key, value) == (present[slot] ? values[slot] : 0), "FloatByte:put");
                if (!present[slot]) size++;
                present[slot] = true;
                values[slot] = value;
            } else {
                ContractSuite.check(map.remove(key) == (present[slot] ? values[slot] : 0), "FloatByte:remove");
                if (present[slot]) size--;
                present[slot] = false;
            }
            ContractSuite.check(map.size() == size, "FloatByte:size");
            ContractSuite.check(map.containsKey(key) == present[slot], "FloatByte:contains");
            ContractSuite.check(map.get(key) == (present[slot] ? values[slot] : 0), "FloatByte:get");
            if (step % 100 == 0) { map.compact(); map.ensureCapacity(20); }
        }
        TFloatByteHashMap copy = (TFloatByteHashMap)map.clone();
        copy.put((float)100, (byte)17);
        ContractSuite.check(!map.containsKey((float)100), "FloatByte:clone");
        map.transformValues(v -> (byte)(v + 1));
        map.compact();
        map.retainEntries((k, v) -> k >= -20);
        TFloatByteIterator it = map.iterator();
        int seen = 0;
        while (it.hasNext()) {
            it.advance();
            int slot = (int)it.key() + 32;
            ContractSuite.check(it.key() >= -20, "FloatByte:retain");
            ContractSuite.check(it.value() == (byte)(values[slot] + 1), "FloatByte:transform");
            it.setValue((byte)2);
            seen++;
            it.remove();
        }
        ContractSuite.check(map.isEmpty(), "FloatByte:iterator remove");
        ContractSuite.record("FloatByte:visited=" + seen);
        map.put((float)1, (byte)4);
        map.increment((float)1);
        map.adjustValue((float)1, (byte)2);
        ContractSuite.check(map.get((float)1) == 7, "FloatByte:adjust");
        ContractSuite.check(!map.adjustValue((float)2, (byte)1), "FloatByte:adjust missing");
        java.util.Map<Float, Byte> decorated = new TFloatByteHashMapDecorator(map);
        decorated.put((float)2, (byte)9);
        ContractSuite.check(map.get((float)2) == 9, "FloatByte:decorator put");
        decorated.entrySet().iterator().next().setValue((byte)6);
        ContractSuite.check(map.containsValue((byte)6), "FloatByte:decorator entry");
        decorated.clear();
        ContractSuite.check(map.isEmpty(), "FloatByte:decorator clear");
    }


