    static void testDoubleCollections() {
        TDoubleHashSet set = new TDoubleHashSet(new double[] {1, 2, 2, 3});
        ContractSuite.check(set.size() == 3 && !set.add((double)2), "Double:set duplicates");
        set.removeAll(new double[] {2, 4});
        set.addAll(new double[] {4, 5});
        set.retainAll(new double[] {1, 4});
        ContractSuite.check(set.containsAll(new double[] {1, 4}) && set.size() == 2, "Double:set bulk");
        TDoubleHashSet clone = (TDoubleHashSet)set.clone();
        clone.clear();
        ContractSuite.check(set.size() == 2, "Double:set clone");
        java.util.Set<Double> decorated = new TDoubleHashSetDecorator(set);
        decorated.remove((double)1);
        ContractSuite.check(!set.contains((double)1), "Double:set decorator");
        TDoubleIterator iterator = set.iterator();
        iterator.next(); iterator.remove();
        ContractSuite.check(set.isEmpty(), "Double:set iterator");

        TDoubleArrayList list = new TDoubleArrayList(new double[] {1, 2, 3});
        list.insert(1, new double[] {4, 5});
        ContractSuite.check(list.size() == 5 && list.get(2) == 5, "Double:list insert");
        list.remove(1, 2); list.add((double)4); list.reverse();
        ContractSuite.check(list.get(0) == 4 && list.get(3) == 1, "Double:list reverse");
        list.sort();
        ContractSuite.check(list.binarySearch((double)3) == 2, "Double:list search");
        list.fill(1, 3, (double)7);
        ContractSuite.check(list.get(1) == 7 && list.get(0) == 1, "Double:list fill");
        list.transformValues(v -> (double)(v + 1));
        ContractSuite.check(list.grep(v -> v > 5).size() == 2, "Double:list grep");
        ContractSuite.check(list.inverseGrep(v -> v > 5).size() == 2, "Double:list inverseGrep");
        TDoubleArrayList copy = (TDoubleArrayList)list.clone();
        copy.set(0, (double)42);
        ContractSuite.check(list.get(0) == 2, "Double:list clone");
        double[] target = new double[8]; list.toNativeArray(target, 0, list.size());
        ContractSuite.check(target[0] == 2 && target[4] == 0, "Double:list array");
        list.resetQuick(); list.add((double)9); list.trimToSize();
        ContractSuite.check(list.size() == 1 && list.get(0) == 9, "Double:list reset");

        TObjectDoubleHashMap<String> objects = new TObjectDoubleHashMap<>();
        objects.put("zero", (double)0); objects.put("one", (double)1);
        ContractSuite.check(objects.containsKey("zero") && !objects.containsKey("missing"), "Double:object sentinel");
        objects.adjustValue("one", (double)2);
        ContractSuite.check(objects.get("one") == 3, "Double:object adjustment");
        objects.transformValues(v -> (double)(v + 2));
        objects.retainEntries((k, v) -> k.equals("one"));
        ContractSuite.check(objects.size() == 1 && objects.get("one") == 5, "Double:object retain");
        new TObjectDoubleHashMapDecorator<String>(objects).clear();
        ContractSuite.check(objects.isEmpty(), "Double:object decorator");

        TDoubleObjectHashMap<String> primitive = new TDoubleObjectHashMap<>();
        primitive.put((double)0, null); primitive.put((double)1, "one");
        ContractSuite.check(primitive.containsKey((double)0) && primitive.get((double)0) == null, "Double:primitive null");
        TDoubleObjectHashMap<String> pc = (TDoubleObjectHashMap<String>)primitive.clone();
        pc.put((double)1, "copy");
        ContractSuite.check(primitive.get((double)1).equals("one"), "Double:primitive clone");
        new TDoubleObjectHashMapDecorator<String>(primitive).remove((double)1);
        ContractSuite.check(!primitive.containsKey((double)1), "Double:primitive decorator");
    }

